import { describe, test, expect } from 'vitest';
import { render } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

describe('Sample React Challenge', () => {
  test('Renders <h1> with "Hello CoderX"', async () => {
    const { container: root } = render(<App />);
    const h1 = root.querySelector('h1');
    if (!h1) throw new Error('No <h1> element found');
    if (!h1.textContent.includes('Hello CoderX')) {
      throw new Error('Heading text must contain "Hello CoderX"');
    }
  });
});
